     1	import java.util.List;
     2	import java.util.Map;
     3	import java.util.Set;
     4	import java.util.stream.Collectors;
     5	
     6	/**
     7	 * The MHPCO pricing policy for components: 25 G base premium each, with a
     8	 * building block of exactly 3 alike components offered at 60 G.
     9	 */
    10	public final class ComponentPricing {
    11	
    12	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    13	
    14	    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;
    15	
    16	    private static final int COMPONENTS_PER_BLOCK = 3;
    17	
    18	    private static final int BLOCK_BASE_PREMIUM_IN_G = 60;
    19	
    20	    private ComponentPricing() {
    21	    }
    22	
    23	    public static boolean isComponent(String itemType) {
    24	        return COMPONENT_TYPES.contains(itemType);
    25	    }
    26	
    27	    /**
    28	     * The base premium for every component in a policy: components are grouped
    29	     * into sets of alike components, and each set is priced on its own.
    30	     */
    31	    public static int componentsBasePremium(List<Item> items) {
    32	        Map<String, Long> alikeCounts = items.stream()
    33	                .filter(item -> isComponent(item.type()))
    34	                .collect(Collectors.groupingBy(ComponentPricing::alikeGroup, Collectors.counting()));
    35	        return alikeCounts.values().stream()
    36	                .mapToInt(count -> alikeComponentsBasePremium(count.intValue()))
    37	                .sum();
    38	    }
    39	
    40	    /**
    41	     * Components are alike when they are of the same item type: a rune and a
    42	     * moonstone are never alike, however rune-y or gemstone-y they look. This
    43	     * is the one place the MHPCO's reading of "alike" is decided.
    44	     */
    45	    private static String alikeGroup(Item item) {
    46	        return item.type();
    47	    }
    48	
    49	    private static int alikeComponentsBasePremium(int count) {
    50	        if (formsABlock(count)) {
    51	            return BLOCK_BASE_PREMIUM_IN_G;
    52	        }
    53	        return count * COMPONENT_BASE_PREMIUM_IN_G;
    54	    }
    55	
    56	    /**
    57	     * The MHPCO offers the block only for exactly 3 alike components: 4 alike
    58	     * components are not a block plus a spare, and 7 are not two blocks plus a
    59	     * spare -- each of those is charged at the full per-component premium.
    60	     */
    61	    private static boolean formsABlock(int alikeCount) {
    62	        return alikeCount == COMPONENTS_PER_BLOCK;
    63	    }
    64	}
