     1	/**
     2	 * The MHPCO's policy-wide premium modifiers. Unlike the item-specific risk
     3	 * surcharges, these are measured against the policy premium as a whole and
     4	 * depend on the customer's history with the MHPCO rather than on any item.
     5	 *
     6	 * This is the one place that says which modifiers are policy-wide: the initial
     7	 * assessment surcharge and the follow-up contract discount are added here and
     8	 * nowhere else.
     9	 */
    10	public final class PolicyWideModifiers {
    11	
    12	    private static final int LOYALTY_YEARS = 2;
    13	
    14	    private static final int LOYALTY_DISCOUNT_PERCENT = 20;
    15	
    16	    private final Customer customer;
    17	
    18	    public PolicyWideModifiers(Customer customer) {
    19	        this.customer = customer;
    20	    }
    21	
    22	    /**
    23	     * The net effect of every policy-wide modifier on a policy premium:
    24	     * positive amounts are charged to the customer, negative amounts are
    25	     * granted to the customer.
    26	     */
    27	    public int totalPolicyModifiers(int policyPremium) {
    28	        return -loyaltyDiscount(policyPremium);
    29	    }
    30	
    31	    /**
    32	     * Long-standing customers -- 2 or more years of business with the MHPCO --
    33	     * receive a 20 % loyalty discount on the policy premium.
    34	     */
    35	    private int loyaltyDiscount(int policyPremium) {
    36	        if (customer.yearsWithMHPCO() < LOYALTY_YEARS) {
    37	            return 0;
    38	        }
    39	        return policyPremium * LOYALTY_DISCOUNT_PERCENT / 100;
    40	    }
    41	}

